//! Ecliptic Remote Desktop network transport layer.

/// Placeholder API for the network crate scaffold.
pub fn placeholder() {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn placeholder_is_callable() {
        placeholder();
    }
}

import XCTest

// Crypto + wire-protocol unit tests: HKDF (RFC 5869), AES-GCM datagram
// cipher with replay window, bounds-checked parsing, handshake v3, pairing.

final class HKDFTests: XCTestCase {
    // RFC 5869 Appendix A, Test Case 1 (SHA-256)
    func testRFC5869Case1() {
        let ikm = Data(repeating: 0x0b, count: 22)
        let salt = Data([0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c])
        let info = Data([0xf0, 0xf1, 0xf2, 0xf3, 0xf4, 0xf5, 0xf6, 0xf7, 0xf8, 0xf9])
        let okm = HKDF.derive(ikm: ikm, salt: salt, info: info, length: 42)
        let expected = Data([
            0x3c, 0xb2, 0x5f, 0x25, 0xfa, 0xac, 0xd5, 0x7a, 0x90, 0x43, 0x4f, 0x64, 0xd0, 0x36, 0x2f, 0x2a,
            0x2d, 0x2d, 0x0a, 0x90, 0xcf, 0x1a, 0x5a, 0x4c, 0x5d, 0xb0, 0x2d, 0x56, 0xec, 0xc4, 0xc5, 0xbf,
            0x34, 0x00, 0x72, 0x08, 0xd5, 0xb8, 0x87, 0x18, 0x58, 0x65])
        XCTAssertEqual(okm, expected)
    }

    // RFC 5869 Appendix A, Test Case 3 (SHA-256, empty salt/info)
    func testRFC5869Case3() {
        let ikm = Data(repeating: 0x0b, count: 22)
        let okm = HKDF.derive(ikm: ikm, salt: Data(), info: Data(), length: 42)
        let expected = Data([
            0x8d, 0xa4, 0xe7, 0x75, 0xa5, 0x63, 0xc1, 0x8f, 0x71, 0x5f, 0x80, 0x2a, 0x06, 0x3c, 0x5a, 0x31,
            0xb8, 0xa1, 0x1f, 0x5c, 0x5e, 0xe1, 0x87, 0x9e, 0xc3, 0x45, 0x4e, 0x5f, 0x3c, 0x73, 0x8d, 0x2d,
            0x9d, 0x20, 0x13, 0x95, 0xfa, 0xa4, 0xb6, 0x1a, 0x96, 0xc8])
        XCTAssertEqual(okm, expected)
    }
}

final class DatagramCipherTests: XCTestCase {
    private func makeMatchingPair() -> (sender: DatagramCipher, receiver: DatagramCipher) {
        let master = ERDCrypto.randomKey()
        let salt = ERDCrypto.randomKey().prefix(16)
        let sender = DatagramCipher.udpCipher(masterKey: master, sessionSalt: salt, clientToHost: true)
        let receiver = DatagramCipher.udpCipher(masterKey: master, sessionSalt: salt, clientToHost: true)
        return (sender, receiver)
    }

    private let aad = Data("erd-packet-header".utf8)

    func testSealOpenRoundtrip() {
        let (sender, receiver) = makeMatchingPair()
        let plaintext = Data((0..<1000).map { _ in UInt8.random(in: 0...255) })
        let datagram = sender.seal(plaintext, aad: aad)
        XCTAssertNotNil(datagram)
        XCTAssertEqual(datagram!.count, plaintext.count + DatagramCipher.nonceSize + DatagramCipher.tagSize)
        XCTAssertEqual(receiver.open(datagram!, aad: aad), plaintext)
    }

    func testTamperedDatagramRejected() {
        let (sender, receiver) = makeMatchingPair()
        var datagram = sender.seal(Data("payload".utf8), aad: aad)!
        datagram[datagram.count - 1] ^= 0xFF
        XCTAssertNil(receiver.open(datagram, aad: aad))
    }

    func testAADMismatchRejected() {
        let (sender, receiver) = makeMatchingPair()
        let datagram = sender.seal(Data("payload".utf8), aad: aad)
        XCTAssertNil(receiver.open(datagram!, aad: Data("different".utf8)))
    }

    func testDuplicateDatagramRejected() {
        let (sender, receiver) = makeMatchingPair()
        let datagram = sender.seal(Data("once".utf8), aad: aad)!
        XCTAssertNotNil(receiver.open(datagram, aad: aad))
        XCTAssertNil(receiver.open(datagram, aad: aad))
    }

    func testStaleDatagramOutsideWindowRejected() {
        let (sender, receiver) = makeMatchingPair()
        var datagrams: [Data] = []
        for _ in 0...Int(DatagramCipher.windowSize) + 8 {
            datagrams.append(sender.seal(Data("stale".utf8), aad: aad)!)
        }
        // Receiver advances to the newest packet first
        XCTAssertNotNil(receiver.open(datagrams.last!, aad: aad))
        // The oldest packet is now far outside the replay window
        XCTAssertNil(receiver.open(datagrams.first!, aad: aad))
    }

    func testDirectionKeysAreIndependent() {
        let master = ERDCrypto.randomKey()
        let salt = ERDCrypto.randomKey().prefix(16)
        let clientSend = DatagramCipher.udpCipher(masterKey: master, sessionSalt: salt, clientToHost: true)
        let wrongReceiver = DatagramCipher.udpCipher(masterKey: master, sessionSalt: salt, clientToHost: false)
        let datagram = clientSend.seal(Data("cross".utf8), aad: aad)
        XCTAssertNil(wrongReceiver.open(datagram!, aad: aad))
    }
}

final class PacketBoundsTests: XCTestCase {
    func testTruncatedPacketHeaderRejected() {
        let header = PacketHeader(type: .frameHeader, sequence: 1, timestamp: 2)
        let data = header.serialize()
        XCTAssertNil(PacketHeader.deserialize(from: data.prefix(ERDConstants.packetHeaderSize - 1)))
    }

    func testUnknownPacketTypeRejected() {
        var data = PacketHeader(type: .ping, sequence: 1, timestamp: 2).serialize()
        data[2] = 0xEE
        XCTAssertNil(PacketHeader.deserialize(from: data))
    }

    func testOversizedFrameTotalSizeRejected() {
        let header = FrameHeaderPayload(frameId: 1, width: 16, height: 16, isKeyFrame: true,
                                        totalChunks: 2, totalSize: UInt32(ERDConstants.maxFrameBytes + 1))
        XCTAssertNil(FrameHeaderPayload.deserialize(from: header.serialize()))
    }

    func testOversizedChunkCountRejected() {
        let header = FrameHeaderPayload(frameId: 1, width: 16, height: 16, isKeyFrame: true,
                                        totalChunks: ERDConstants.maxChunksPerFrame + 1, totalSize: 1024)
        XCTAssertNil(FrameHeaderPayload.deserialize(from: header.serialize()))
    }

    func testHandshakeV3RoundtripCarriesIdentityAndSalt() {
        let salt = ERDCrypto.randomKey().prefix(16)
        let hs = HandshakePayload(hostname: "host-a", screenWidth: 2560, screenHeight: 1440,
                                  scaleFactor: 2.0, capabilities: [.streamConfiguration],
                                  pairingID: "ABCD-1234", sessionSalt: salt)
        let decoded = HandshakePayload.deserialize(from: hs.serialize())
        XCTAssertNotNil(decoded)
        XCTAssertEqual(decoded?.pairingID, "ABCD-1234")
        XCTAssertEqual(decoded?.sessionSalt, salt)
        XCTAssertEqual(decoded?.protocolVersion, ERDConstants.protocolVersion)
    }

    func testHandshakeWithoutV3TailIsAccepted() {
        let hs = HandshakePayload(hostname: "legacy-shape", screenWidth: 1920, screenHeight: 1080, scaleFactor: 1.0)
        let decoded = HandshakePayload.deserialize(from: hs.serialize())
        XCTAssertNotNil(decoded)
        XCTAssertEqual(decoded?.pairingID, "")
        XCTAssertEqual(decoded?.sessionSalt, Data())
    }
}

final class PairingTests: XCTestCase {
    func testRandomPINFormat() {
        for _ in 0..<20 {
            let pin = ERDCrypto.randomPIN()
            XCTAssertEqual(pin.count, ERDConstants.pinLength)
            XCTAssertTrue(pin.allSatisfy { $0.isNumber })
        }
    }

    func testBootstrapPSKIsDeterministicPerPIN() {
        XCTAssertEqual(ERDCrypto.bootstrapPSK(pin: "12345678"), ERDCrypto.bootstrapPSK(pin: "12345678"))
        XCTAssertNotEqual(ERDCrypto.bootstrapPSK(pin: "12345678"), ERDCrypto.bootstrapPSK(pin: "87654321"))
    }

    func testPairingPayloadRoundtrips() {
        let request = PairingRequestPayload(hostname: "client-mac")
        XCTAssertEqual(PairingRequestPayload.deserialize(from: request.serialize())?.hostname, "client-mac")

        let grant = PairingGrantPayload(pairingID: "UUID-1", hostName: "host-mac", key: ERDCrypto.randomKey())
        let decodedGrant = PairingGrantPayload.deserialize(from: grant.serialize())
        XCTAssertEqual(decodedGrant?.pairingID, "UUID-1")
        XCTAssertEqual(decodedGrant?.hostName, "host-mac")
        XCTAssertEqual(decodedGrant?.key, grant.key)

        let reject = PairingRejectPayload(reason: .deniedByHost)
        XCTAssertEqual(PairingRejectPayload.deserialize(from: reject.serialize())?.reason, .deniedByHost)
    }

    func testGrantWithWrongKeyLengthRejected() {
        let grant = PairingGrantPayload(pairingID: "UUID-2", hostName: "host", key: Data(repeating: 1, count: 31))
        XCTAssertNil(PairingGrantPayload.deserialize(from: grant.serialize()))
    }

    func testPairingStoreRoundtrip() {
        let record = PairingRecord(name: "test-device-\(UUID().uuidString)", key: ERDCrypto.randomKey())
        XCTAssertTrue(PairingStore.save(record))
        XCTAssertEqual(PairingStore.load(id: record.id), record)
        XCTAssertTrue(PairingStore.delete(id: record.id))
        XCTAssertNil(PairingStore.load(id: record.id))
    }

    func testBootstrapLockoutAfterRepeatedFailures() {
        PairingManager.shared.beginPairing()
        var lockedOut = false
        for _ in 0..<ERDConstants.maxPairingAttempts {
            lockedOut = PairingManager.shared.recordBootstrapFailure()
        }
        XCTAssertTrue(lockedOut)
        XCTAssertFalse(PairingManager.shared.hostPSKs().contains { $0.identity == PairingManager.bootstrapIdentity })
        // A fresh pairing window clears the lockout
        PairingManager.shared.beginPairing()
        XCTAssertTrue(PairingManager.shared.hostPSKs().contains { $0.identity == PairingManager.bootstrapIdentity })
        PairingManager.shared.cancelPairing()
    }
}

import Foundation
import CryptoKit
import Security
import CommonCrypto

// Cryptographic core of the v3 wire protocol.
//
// TCP runs TLS 1.3 with external PSKs: a bootstrap PSK derived from an
// 8-digit PIN plus a per-connection salt, or a 256-bit random pairing key
// persisted in the Keychain after first approval (see ERDIdentity).
// UDP datagrams are sealed with AES-256-GCM under direction-separated keys
// derived from the pairing key and a per-session salt.
//
// HKDF is implemented locally because CryptoKit's HKDF API requires macOS 14
// while EclipticRD targets macOS 13.

/// RFC 5869 HKDF-SHA256 (Extract/Expand); test vectors live in the XCTest target.
enum HKDF {
    static func extract(salt: Data, ikm: Data) -> Data {
        let key = SymmetricKey(data: salt.isEmpty ? Data(repeating: 0, count: 32) : salt)
        return Data(HMAC<SHA256>.authenticationCode(for: ikm, using: key))
    }

    static func expand(prk: Data, info: Data, length: Int) -> Data {
        precondition(length >= 0 && length <= 255 * 32, "HKDF-Expand length out of range")
        var okm = Data()
        var t = Data()
        var counter: UInt8 = 1
        while okm.count < length {
            var input = t
            input.append(info)
            input.append(counter)
            t = Data(HMAC<SHA256>.authenticationCode(for: input, using: SymmetricKey(data: prk)))
            okm.append(t)
            counter &+= 1
        }
        return okm.prefix(length)
    }

    static func derive(ikm: Data, salt: Data, info: Data, length: Int = 32) -> Data {
        expand(prk: extract(salt: salt, ikm: ikm), info: info, length: length)
    }
}

/// AES-256-GCM cipher for UDP datagrams with sliding-window replay protection.
///
/// Datagram wire format: `[12-byte nonce][ciphertext][16-byte tag]`
/// Nonce layout: `[4-byte session prefix][8-byte big-endian packet counter]`.
/// Prefix and traffic key are direction-separated, so nonce reuse across the
/// two directions is impossible even under counter resets.
public final class DatagramCipher: @unchecked Sendable {
    public static let nonceSize = 12
    public static let tagSize = 16
    public static let windowSize: UInt64 = 4096

    private let key: SymmetricKey
    private let noncePrefix: [UInt8] // 4 bytes, derived per direction per session
    private let lock = NSLock()
    private var sendCounter: UInt64 = 0
    private var highestReceived: UInt64 = 0
    private var receivedBlocks: [UInt64: UInt64] = [:] // block index -> 64-bit seen mask

    init(key: Data, noncePrefix: Data) {
        precondition(key.count == 32, "DatagramCipher expects a 256-bit key")
        precondition(noncePrefix.count == 4, "DatagramCipher expects a 4-byte nonce prefix")
        self.key = SymmetricKey(data: key)
        self.noncePrefix = [UInt8](noncePrefix)
    }

    /// Derive the per-direction UDP traffic cipher from the pairing master key
    /// and the session salt exchanged inside the authenticated handshake.
    public static func udpCipher(masterKey: Data, sessionSalt: Data, clientToHost: Bool) -> DatagramCipher {
        let ikm = HKDF.derive(ikm: masterKey, salt: sessionSalt, info: Data("erd/udp-ikm/v3".utf8))
        let info = Data(clientToHost ? "erd/udp-c2h/v3".utf8 : "erd/udp-h2c/v3".utf8)
        let key = HKDF.derive(ikm: ikm, salt: sessionSalt, info: info, length: 32)
        let prefix = HKDF.derive(ikm: ikm, salt: sessionSalt, info: info + Data("/nonce".utf8), length: 4)
        return DatagramCipher(key: key, noncePrefix: prefix)
    }

    /// Encrypt `plaintext`; returns nonce||ciphertext||tag, or nil on internal failure.
    public func seal(_ plaintext: Data, aad: Data = Data()) -> Data? {
        lock.lock()
        sendCounter &+= 1
        let counter = sendCounter
        lock.unlock()

        var nonceBytes = noncePrefix
        var bigCounter = counter.bigEndian
        withUnsafeBytes(of: &bigCounter) { nonceBytes.append(contentsOf: $0) }
        guard let nonce = try? AES.GCM.Nonce(data: Data(nonceBytes)),
              let box = try? AES.GCM.seal(plaintext, using: key, nonce: nonce, authenticating: aad)
        else { return nil }
        return Data(nonceBytes) + box.ciphertext + box.tag
    }

    /// Decrypt a datagram produced by `seal`. Returns nil for tampered,
    /// duplicated, or too-old packets. Thread-safe.
    public func open(_ datagram: Data, aad: Data = Data()) -> Data? {
        guard datagram.count > Self.nonceSize + Self.tagSize else { return nil }
        let nonceData = datagram.subdata(in: 0..<Self.nonceSize)
        let counter = nonceData.subdata(in: 4..<12).withUnsafeBytes { $0.load(as: UInt64.self).bigEndian }
        let ciphertext = datagram.subdata(in: Self.nonceSize..<(datagram.count - Self.tagSize))
        let tag = datagram.subdata(in: (datagram.count - Self.tagSize)..<datagram.count)

        lock.lock(); defer { lock.unlock() }

        // Replay window fast reject (overflow-safe: never add to a wire value).
        guard highestReceived <= counter || highestReceived - counter < Self.windowSize else { return nil }
        let block = counter / 64
        let mask: UInt64 = 1 << (counter % 64)
        if (receivedBlocks[block] ?? 0) & mask != 0 { return nil }

        guard let nonce = try? AES.GCM.Nonce(data: nonceData),
              let box = try? AES.GCM.SealedBox(nonce: nonce, ciphertext: ciphertext, tag: tag),
              let plaintext = try? AES.GCM.open(box, using: key, authenticating: aad)
        else { return nil }

        receivedBlocks[block, default: 0] |= mask
        if counter > highestReceived { highestReceived = counter }
        let cutoff = highestReceived >= Self.windowSize ? (highestReceived - Self.windowSize) / 64 : 0
        if receivedBlocks.count > 128 {
            receivedBlocks = receivedBlocks.filter { $0.key >= cutoff }
        }
        return plaintext
    }
}

/// Shared helpers for the identity material backing the TLS-PSK channels.
public enum ERDCrypto {
    /// TLS-PSK for a bootstrap (first-time pairing) connection. The host
    /// rotates the PIN per pairing session, so each session gets a fresh key
    /// without per-connection salt negotiation.
    ///
    /// The PIN is PBKDF2-stretched so an attacker who records the bootstrap
    /// handshake cannot brute-force it offline with cheap HMAC evaluations.
    public static func bootstrapPSK(pin: String) -> Data {
        let stretched = stretch(Data(pin.utf8),
                                salt: Data("erd/bootstrap/v3".utf8),
                                rounds: ERDConstants.bootstrapPINStretchRounds)
        return HKDF.derive(ikm: stretched,
                           salt: Data("erd/bootstrap/v3".utf8),
                           info: Data("erd/tls-psk".utf8))
    }

    /// PBKDF2-SHA256 (CommonCrypto), 32-byte output. Roughly 0.3s per call at
    /// the configured round count — the derivation runs once per pairing
    /// window, never per packet.
    private static func stretch(_ secret: Data, salt: Data, rounds: UInt32) -> Data {
        var derived = Data(repeating: 0, count: 32)
        let status = derived.withUnsafeMutableBytes { derivedBytes in
            secret.withUnsafeBytes { secretBytes in
                salt.withUnsafeBytes { saltBytes in
                    CCKeyDerivationPBKDF(
                        CCPBKDFAlgorithm(kCCPBKDF2),
                        secretBytes.baseAddress?.assumingMemoryBound(to: Int8.self), secret.count,
                        saltBytes.baseAddress?.assumingMemoryBound(to: UInt8.self), salt.count,
                        CCPseudoRandomAlgorithm(kCCPRFHmacAlgSHA256), rounds,
                        derivedBytes.baseAddress?.assumingMemoryBound(to: UInt8.self), 32)
                }
            }
        }
        precondition(status == kCCSuccess, "PBKDF2 failed: \(status)")
        return derived
    }

    /// PSK for a paired device: the raw 256-bit Keychain pairing key.
    public static func pairingPSK(_ key: Data) -> Data { key }

    /// Uniform 32-byte random key material.
    public static func randomKey() -> Data {
        var key = Data(count: 32)
        let status = key.withUnsafeMutableBytes {
            SecRandomCopyBytes(kSecRandomDefault, 32, $0.baseAddress!)
        }
        precondition(status == errSecSuccess, "SecRandomCopyBytes failed: \(status)")
        return key
    }

    /// 8-digit zero-padded bootstrap PIN from the system RNG.
    public static func randomPIN(digits: Int = ERDConstants.pinLength) -> String {
        var value: UInt64 = 0
        let bound = UInt64(1) << (6 * digits) // keep modulo bias negligible
        repeat {
            let status = withUnsafeMutableBytes(of: &value) {
                SecRandomCopyBytes(kSecRandomDefault, 8, $0.baseAddress!)
            }
            precondition(status == errSecSuccess, "SecRandomCopyBytes failed: \(status)")
        } while value >= UInt64.max - (UInt64.max % bound)
        let modulus = UInt64(pow(10.0, Double(digits)))
        let number = String(value % modulus)
        return String(repeating: "0", count: max(0, digits - number.count)) + number
    }
}

import Foundation
import CryptoKit

public struct SessionCandidate: Codable, Equatable {
    public let role: String
    public let localIP: String
    public let localPort: UInt16
    public let publicIP: String
    public let publicPort: UInt16

    public init(role: String, localIP: String, localPort: UInt16, publicIP: String, publicPort: UInt16) {
        self.role = role; self.localIP = localIP; self.localPort = localPort
        self.publicIP = publicIP; self.publicPort = publicPort
    }
}

/// NAT-traversal candidate exchange over a public ntfy.sh topic.
///
/// The topic is a 256-bit hash of the shared PIN and candidate payloads are
/// AES-GCM encrypted under a key derived from the same PIN, so an outside
/// observer can neither enumerate topics for a given PIN space nor read the
/// exchanged addresses. Both peers poll until the other side's candidate
/// shows up instead of failing on the first empty response.
public class SignalingClient {
    private let role: String
    private let topic: String
    private let payloadKey: SymmetricKey
    private let lock = NSLock()
    private var isSearching = false

    public init(pin: String, role: String) {
        self.role = role
        let ikm = Data(pin.utf8)
        let seed = HKDF.derive(ikm: ikm, salt: Data("erd/signaling/v3".utf8), info: Data("erd/topic".utf8))
        // ntfy.sh rejects topics longer than 64 chars with a 404; 112 bits of
        // derived entropy keeps the topic unenumerable while fitting the cap.
        self.topic = "erd3-" + seed.prefix(14).map { String(format: "%02x", $0) }.joined()
        let key = HKDF.derive(ikm: ikm, salt: Data("erd/signaling/v3".utf8), info: Data("erd/payload-key".utf8))
        self.payloadKey = SymmetricKey(data: key)
    }

    deinit { stop() }

    private static func encrypt(_ payload: Data, using key: SymmetricKey) throws -> String {
        let box = try AES.GCM.seal(payload, using: key)
        return Data(box.combined!).base64EncodedString()
    }

    private static func peerCandidate(in data: Data, excludingRole role: String, key: SymmetricKey) -> SessionCandidate? {
        let lines = String(data: data, encoding: .utf8)?.split(separator: "\n") ?? []
        for line in lines.reversed() {
            guard let lineData = line.data(using: .utf8),
                  let envelope = try? JSONSerialization.jsonObject(with: lineData) as? [String: Any],
                  let message = envelope["message"] as? String,
                  let raw = Data(base64Encoded: message),
                  let box = try? AES.GCM.SealedBox(combined: raw),
                  let payload = try? AES.GCM.open(box, using: key),
                  let candidate = try? JSONDecoder().decode(SessionCandidate.self, from: payload),
                  candidate.role != role
            else { continue }
            return candidate
        }
        return nil
    }

    public func exchangeCandidate(_ local: SessionCandidate) async throws -> SessionCandidate {
        let payload = try JSONEncoder().encode(local)
        let message = try Self.encrypt(payload, using: payloadKey)
        let url = URL(string: "https://ntfy.sh/\(topic)")!

        var post = URLRequest(url: url)
        post.httpMethod = "POST"
        post.httpBody = Data(message.utf8)
        post.setValue("text/plain", forHTTPHeaderField: "Content-Type")

        ERDLog.network("[Signaling] Posting candidate")
        let (_, postResponse) = try await URLSession.shared.data(for: post)
        if let http = postResponse as? HTTPURLResponse, !(200...299).contains(http.statusCode) {
            throw NSError(domain: "Signaling", code: 3,
                          userInfo: [NSLocalizedDescriptionKey: "Candidate POST rejected (HTTP \(http.statusCode))"])
        }

        lock.lock()
        isSearching = true
        lock.unlock()

        let deadline = Date().addingTimeInterval(ERDConstants.connectionTimeout)
        var poll = URLRequest(url: URL(string: "https://ntfy.sh/\(topic)/json?poll=1&since=10m")!)
        poll.timeoutInterval = 10

        while Date() < deadline {
            lock.lock()
            let active = isSearching
            lock.unlock()
            guard active else { throw CancellationError() }
            try Task.checkCancellation()

            if let (data, _) = try? await URLSession.shared.data(for: poll),
               let candidate = Self.peerCandidate(in: data, excludingRole: role, key: payloadKey) {
                return candidate
            }
            try await Task.sleep(nanoseconds: 1_000_000_000)
        }
        throw NSError(domain: "Signaling", code: 2,
                      userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"])
    }

    public func stop() {
        lock.lock()
        isSearching = false
        lock.unlock()
    }
}

import Foundation
import Network

public class STUNClient {
    private let serverHost: String
    private let serverPort: UInt16

    public init(serverHost: String = "stun.l.google.com", serverPort: UInt16 = 19302) {
        self.serverHost = serverHost
        self.serverPort = serverPort
    }

    public func fetchPublicIP() async throws -> (String, UInt16) {
        return try await withCheckedThrowingContinuation { continuation in
            let queue = DispatchQueue(label: "eclipticrd.stun")
            let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(serverHost), port: NWEndpoint.Port(rawValue: serverPort)!)
            let params = NWParameters.udp
            if let ip = params.defaultProtocolStack.internetProtocol as? NWProtocolIP.Options {
                ip.version = .v4
            }
            let conn = NWConnection(to: endpoint, using: params)
            var completed = false

            func finish(result: Result<(String, UInt16), Error>) {
                guard !completed else { return }
                completed = true
                conn.cancel()
                switch result {
                case .success(let v): continuation.resume(returning: v)
                case .failure(let e): continuation.resume(throwing: e)
                }
            }

            conn.stateUpdateHandler = { [self] state in
                switch state {
                case .ready:
                    var request = Data(count: 20)
                    request[0] = 0x00; request[1] = 0x01
                    request[4] = 0x21; request[5] = 0x12; request[6] = 0xA4; request[7] = 0x42
                    for i in 8..<20 { request[i] = UInt8.random(in: 0...255) }

                    conn.send(content: request, completion: .contentProcessed { _ in })

                    conn.receiveMessage { data, _, _, error in
                        if let error = error {
                            finish(result: .failure(error))
                            return
                        }
                        guard let data = data, data.count >= 20 else {
                            finish(result: .failure(NSError(domain: "STUN", code: 1, userInfo: [NSLocalizedDescriptionKey: "Empty STUN response"])))
                            return
                        }
                        if let (ip, port) = Self.parseMappedAddress(from: data) {
                            finish(result: .success((ip, port)))
                        } else {
                            finish(result: .failure(NSError(domain: "STUN", code: 2, userInfo: [NSLocalizedDescriptionKey: "MAPPED-ADDRESS not found in STUN response"])))
                        }
                    }
                case .failed(let error):
                    finish(result: .failure(error))
                default:
                    break
                }
            }

            conn.start(queue: queue)

            queue.asyncAfter(deadline: .now() + 5.0) {
                finish(result: .failure(NSError(domain: "STUN", code: 3, userInfo: [NSLocalizedDescriptionKey: "STUN timeout"])))
            }
        }
    }

    private static func parseMappedAddress(from data: Data) -> (String, UInt16)? {
        let magicCookie: UInt32 = 0x2112A442
        var offset = 20 // Skip header

        while offset + 4 <= data.count {
            let attrType = UInt16(data[offset]) << 8 | UInt16(data[offset+1])
            let attrLen = Int(UInt16(data[offset+2]) << 8 | UInt16(data[offset+3]))
            offset += 4

            guard offset + attrLen <= data.count else { break }

            if attrType == 0x0020 { // XOR-MAPPED-ADDRESS
                guard attrLen >= 8 else { break }
                let family = data[offset + 1]
                let xPort = (UInt16(data[offset+2]) << 8 | UInt16(data[offset+3])) ^ UInt16(magicCookie >> 16)

                if family == 0x01 { // IPv4
                    let xAddr = UInt32(data[offset+4]) << 24 | UInt32(data[offset+5]) << 16 |
                                UInt32(data[offset+6]) << 8  | UInt32(data[offset+7])
                    let addr = xAddr ^ magicCookie
                    let ip = "\(addr >> 24 & 0xFF).\(addr >> 16 & 0xFF).\(addr >> 8 & 0xFF).\(addr & 0xFF)"
                    return (ip, xPort)
                }
            } else if attrType == 0x0001 { // MAPPED-ADDRESS (fallback)
                guard attrLen >= 8 else { break }
                let family = data[offset + 1]
                let port = UInt16(data[offset+2]) << 8 | UInt16(data[offset+3])

                if family == 0x01 {
                    let ip = "\(data[offset+4]).\(data[offset+5]).\(data[offset+6]).\(data[offset+7])"
                    return (ip, port)
                }
            }

            // Attributes are padded to 4-byte boundaries
            offset += (attrLen + 3) & ~3
        }
        return nil
    }
}

import Foundation
import Security

// Pairing identity, Keychain storage, and bootstrap PIN state.
//
// First contact: the client offers TLS-PSK identity "erd-b1.<salt>", whose
// key derives from the host's 8-digit bootstrap PIN. The host approves the
// device with an explicit prompt before any input or screen access is
// granted, and repeated PIN failures lock the bootstrap path globally.
// On approval the host generates a 256-bit pairing key and hands it to the
// client over the encrypted channel; both sides persist it in the Keychain.
// Later sessions use identity "erd-p1.<uuid>" with that key, which cannot
// be brute-forced offline the way the PIN can.
//
// Residual risk: an attacker who records the bootstrap handshake and cracks
// the PIN offline recovers that one session and the pairing key. Consent,
// lockout, and PIN expiry mitigate this; SPAKE2+ is the follow-up once a
// vetted Swift PAKE implementation is available.

/// A persisted trust relationship with one remote device.
public struct PairingRecord: Codable, Equatable, Identifiable, Sendable {
    public let id: String
    public var name: String
    public let key: Data
    public let addedAt: Date

    public init(id: String = UUID().uuidString, name: String, key: Data, addedAt: Date = Date()) {
        self.id = id
        self.name = name
        self.key = key
        self.addedAt = addedAt
    }

    public var pskIdentity: String { "erd-p1.\(id)" }
}

/// File-backed storage for pairing records.
///
/// Plaintext by design (user decision, 2026-09-01): the pairing key only
/// protects the network path — anyone with this user's disk access already
/// controls the machine, so the OS keychain adds friction (locked keychains
/// break headless/test sessions) without raising the real bar. File is 0600
/// under the user's Application Support directory.
public enum PairingStore {
    private static let fileLock = NSLock()

    private static var storeURL: URL {
        let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("EclipticRD", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir.appendingPathComponent("pairing-keys.json")
    }

    public static func loadAll() -> [PairingRecord] {
        fileLock.lock()
        defer { fileLock.unlock() }
        return loadAllUnlocked()
    }

    public static func load(id: String) -> PairingRecord? {
        loadAll().first { $0.id == id }
    }

    @discardableResult
    public static func save(_ record: PairingRecord) -> Bool {
        fileLock.lock()
        defer { fileLock.unlock() }
        // NSLock is not reentrant: call the unlocked variants, never the
        // public locked wrappers, while holding fileLock.
        var records = loadAllUnlocked().filter { $0.id != record.id }
        records.append(record)
        return writeUnlocked(records)
    }

    @discardableResult
    public static func delete(id: String) -> Bool {
        fileLock.lock()
        defer { fileLock.unlock() }
        var records = loadAllUnlocked()
        records.removeAll { $0.id == id }
        return writeUnlocked(records)
    }

    /// Caller must hold fileLock.
    private static func loadAllUnlocked() -> [PairingRecord] {
        guard let data = try? Data(contentsOf: storeURL),
              let records = try? JSONDecoder().decode([PairingRecord].self, from: data)
        else { return [] }
        return records
    }

    /// Caller must hold fileLock. Atomic 0600 write.
    private static func writeUnlocked(_ records: [PairingRecord]) -> Bool {
        guard let data = try? JSONEncoder().encode(records) else { return false }
        do {
            try data.write(to: storeURL, options: .atomic)
            try? FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: storeURL.path)
            return true
        } catch {
            ERDLog.error("[PairingStore] Failed to persist pairing: \(error)")
            return false
        }
    }
}

/// One TLS pre-shared key entry offered on a channel.
public struct ERDPSK: Equatable, Sendable {
    public let identity: String
    public let key: Data

    public init(identity: String, key: Data) {
        self.identity = identity
        self.key = key
    }
}

/// Host-side pairing authority: pending bootstrap PIN state, failure lockout,
/// and the set of PSKs the TCP listener should accept.
public final class PairingManager: @unchecked Sendable {
    public static let shared = PairingManager()

    private struct PendingPairing {
        let pin: String
        let expiresAt: Date
    }

    private let lock = NSLock()
    private var pending: PendingPairing?
    private var failureCount = 0
    private var failureWindowStart = Date.distantPast
    private var bootstrapLockedUntil = Date.distantPast

    // MARK: - Bootstrap PIN lifecycle (host)

    /// Start accepting bootstrap connections; returns the PIN to display.
    /// An explicit numeric PIN of the configured length (internet mode, where
    /// both sides type the same code) overrides the generated one.
    @discardableResult
    public func beginPairing(explicitPIN: String? = nil) -> String {
        var pin = ERDCrypto.randomPIN()
        if let explicitPIN, explicitPIN.count == ERDConstants.pinLength,
           explicitPIN.allSatisfy({ $0.isNumber }) {
            pin = explicitPIN
        }
        let pending = PendingPairing(pin: pin,
                                     expiresAt: Date().addingTimeInterval(ERDConstants.pairingPINExpiry))
        lock.lock()
        self.pending = pending
        failureCount = 0
        bootstrapLockedUntil = .distantPast
        lock.unlock()
        return pin
    }

    public func cancelPairing() {
        lock.lock()
        pending = nil
        lock.unlock()
    }

    public var isPairingActive: Bool {
        lock.withLock { pending != nil && pending!.expiresAt > Date() }
    }

    /// All PSKs the host listener should accept: every paired device plus the
    /// pending bootstrap entry while pairing is active and not locked out.
    public func hostPSKs() -> [ERDPSK] {
        lock.lock(); defer { lock.unlock() }
        var psks = PairingStore.loadAll().map { ERDPSK(identity: $0.pskIdentity, key: ERDCrypto.pairingPSK($0.key)) }
        if let pending, pending.expiresAt > Date(), Date() >= bootstrapLockedUntil {
            psks.append(ERDPSK(identity: Self.bootstrapIdentity,
                               key: ERDCrypto.bootstrapPSK(pin: pending.pin)))
        }
        return psks
    }

    /// Resolve one offered identity to its PSK (used by the TLS verify hook).
    public func resolvePSK(identity: String) -> ERDPSK? {
        hostPSKs().first { $0.identity == identity }
    }

    /// Record a failed bootstrap authentication. Returns true when bootstrap
    /// is now locked out.
    @discardableResult
    public func recordBootstrapFailure() -> Bool {
        lock.lock(); defer { lock.unlock() }
        let now = Date()
        if now.timeIntervalSince(failureWindowStart) > ERDConstants.pairingAttemptWindow {
            failureCount = 0
            failureWindowStart = now
        }
        failureCount += 1
        if failureCount >= ERDConstants.maxPairingAttempts {
            bootstrapLockedUntil = now.addingTimeInterval(ERDConstants.pairingLockout)
            pending = nil
            return true
        }
        return false
    }

    // MARK: - Grant / adopt (both sides)

    /// Host: mint + persist a pairing record for an approved bootstrap peer.
    public func grantPairing(hostname: String) -> PairingRecord {
        let record = PairingRecord(name: hostname, key: ERDCrypto.randomKey())
        PairingStore.save(record)
        return record
    }

    /// Client: persist a pairing record received from a host.
    public func adoptPairing(_ record: PairingRecord) {
        PairingStore.save(record)
    }

    public func pairedDevices() -> [PairingRecord] {
        PairingStore.loadAll().sorted { $0.addedAt > $1.addedAt }
    }

    public func revokePairing(id: String) {
        PairingStore.delete(id: id)
    }

    // MARK: - Client side

    public static let bootstrapIdentity = "erd-b1"

    /// The client connects either with a previously granted pairing key or,
    /// while pairing for the first time, with the bootstrap PSK for `pin`.
    public func clientPSK(pin: String) -> ERDPSK {
        ERDPSK(identity: Self.bootstrapIdentity, key: ERDCrypto.bootstrapPSK(pin: pin))
    }

    public func clientPSK(for record: PairingRecord) -> ERDPSK {
        ERDPSK(identity: record.pskIdentity, key: ERDCrypto.pairingPSK(record.key))
    }
}

private extension NSLock {
    func withLock<T>(_ body: () -> T) -> T {
        lock()
        defer { unlock() }
        return body()
    }
}

