use crate::{codec::usize_to_u32, CodecError};

pub const MAX_TCP_FRAME_SIZE: usize = 16 * 1024 * 1024;

pub struct TcpFrameWriter;

impl TcpFrameWriter {
    pub fn encode(payload: &[u8]) -> Result<Vec<u8>, CodecError> {
        if payload.is_empty() || payload.len() > MAX_TCP_FRAME_SIZE {
            return Err(CodecError::InvalidFrameLength(
                u32::try_from(payload.len()).unwrap_or(u32::MAX),
            ));
        }
        let length = usize_to_u32(payload.len(), "TCP frame")?;
        let mut output = Vec::with_capacity(4 + payload.len());
        output.extend_from_slice(&length.to_le_bytes());
        output.extend_from_slice(payload);
        Ok(output)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TcpFrameEvent {
    Frame(Vec<u8>),
    DroppedInvalidLength(u32),
}

#[derive(Debug, Default)]
pub struct TcpFrameReader {
    buffer: Vec<u8>,
}

impl TcpFrameReader {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn buffered_len(&self) -> usize {
        self.buffer.len()
    }

    pub fn clear(&mut self) {
        self.buffer.clear();
    }

    pub fn push(&mut self, input: &[u8]) -> Vec<TcpFrameEvent> {
        self.buffer.extend_from_slice(input);
        let mut events = Vec::new();

        loop {
            if self.buffer.len() < 4 {
                break;
            }
            let length = u32::from_le_bytes([
                self.buffer[0],
                self.buffer[1],
                self.buffer[2],
                self.buffer[3],
            ]);
            if length == 0 || length as usize > MAX_TCP_FRAME_SIZE {
                self.buffer.clear();
                events.push(TcpFrameEvent::DroppedInvalidLength(length));
                break;
            }
            let frame_end = 4 + length as usize;
            if self.buffer.len() < frame_end {
                break;
            }
            let payload = self.buffer[4..frame_end].to_vec();
            self.buffer.drain(..frame_end);
            events.push(TcpFrameEvent::Frame(payload));
        }

        events
    }
}

//! Pure codecs for the Ecliptic Remote Desktop version 3 wire protocol.
//!
//! This crate performs no I/O. It only converts validated protocol values to
//! and from their byte-exact wire representation and incrementally parses the
//! TCP length-prefix framing used by the transport layer.

mod codec;
mod control;
mod error;
mod framing;
mod handshake;
mod input;
mod media;
mod packet;
mod pairing;

pub use control::*;
pub use error::CodecError;
pub use framing::*;
pub use handshake::*;
pub use input::*;
pub use media::*;
pub use packet::*;
pub use pairing::*;

/// A value with a complete version 3 wire encoding.
pub trait WireCodec: Sized {
    /// Encodes this value into its canonical wire representation.
    fn encode(&self) -> Result<Vec<u8>, CodecError>;

    /// Decodes one complete value from `input`.
    fn decode(input: &[u8]) -> Result<Self, CodecError>;
}

use crate::{codec::Decoder, CodecError, WireCodec};

pub const MAGIC: u16 = 0xec1d;
pub const PROTOCOL_VERSION: u8 = 3;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum PacketType {
    Handshake = 0,
    HandshakeAck = 1,
    FrameHeader = 2,
    FrameChunk = 3,
    CursorUpdate = 4,
    InputEvent = 5,
    Control = 6,
    Ping = 7,
    AudioFrame = 8,
    PairingRequest = 9,
    PairingGrant = 10,
    PairingReject = 11,
}

impl PacketType {
    pub const ALL: [Self; 12] = [
        Self::Handshake,
        Self::HandshakeAck,
        Self::FrameHeader,
        Self::FrameChunk,
        Self::CursorUpdate,
        Self::InputEvent,
        Self::Control,
        Self::Ping,
        Self::AudioFrame,
        Self::PairingRequest,
        Self::PairingGrant,
        Self::PairingReject,
    ];
}

impl TryFrom<u8> for PacketType {
    type Error = CodecError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0 => Ok(Self::Handshake),
            1 => Ok(Self::HandshakeAck),
            2 => Ok(Self::FrameHeader),
            3 => Ok(Self::FrameChunk),
            4 => Ok(Self::CursorUpdate),
            5 => Ok(Self::InputEvent),
            6 => Ok(Self::Control),
            7 => Ok(Self::Ping),
            8 => Ok(Self::AudioFrame),
            9 => Ok(Self::PairingRequest),
            10 => Ok(Self::PairingGrant),
            11 => Ok(Self::PairingReject),
            unknown => Err(CodecError::UnknownPacketType(unknown)),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PacketHeader {
    pub packet_type: PacketType,
    pub sequence: u32,
    pub timestamp_ms: u32,
    pub flags: u8,
}

impl PacketHeader {
    pub const SIZE: usize = 12;

    pub const fn new(packet_type: PacketType, sequence: u32, timestamp_ms: u32, flags: u8) -> Self {
        Self {
            packet_type,
            sequence,
            timestamp_ms,
            flags,
        }
    }
}

impl WireCodec for PacketHeader {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let mut output = Vec::with_capacity(Self::SIZE);
        output.extend_from_slice(&MAGIC.to_le_bytes());
        output.push(self.packet_type as u8);
        output.extend_from_slice(&self.sequence.to_le_bytes());
        output.extend_from_slice(&self.timestamp_ms.to_le_bytes());
        output.push(self.flags);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let magic = decoder.u16("packet magic")?;
        if magic != MAGIC {
            return Err(CodecError::InvalidMagic { found: magic });
        }
        let packet_type = PacketType::try_from(decoder.u8("packet type")?)?;
        let sequence = decoder.u32("packet sequence")?;
        let timestamp_ms = decoder.u32("packet timestamp")?;
        let flags = decoder.u8("packet flags")?;
        decoder.finish("packet header")?;
        Ok(Self {
            packet_type,
            sequence,
            timestamp_ms,
            flags,
        })
    }
}

import Foundation
import Network
import Security

/// Transport security selection for a TCP channel.
///
/// `.psk` upgrades the channel to TLS 1.3 with external pre-shared keys.
/// The host offers one PSK per paired device plus the pending bootstrap key
/// (see PairingManager.hostPSKs); the client offers exactly one. Identity
/// strings on the wire pick the key, so no certificates are involved.
public enum ChannelSecurity {
    case none
    case psk([ERDPSK])

    var tlsParameters: NWParameters? {
        guard case let .psk(psks) = self, !psks.isEmpty else { return nil }
        return Self.tlsOptions(psks)
    }

    static func tlsOptions(_ psks: [ERDPSK]) -> NWParameters {
        let options = NWProtocolTLS.Options()
        let sec = options.securityProtocolOptions
        for psk in psks {
            sec_protocol_options_add_pre_shared_key(sec,
                                                    Self.dispatchData(psk.key) as dispatch_data_t,
                                                    Self.dispatchData(Data(psk.identity.utf8)) as dispatch_data_t)
        }
        sec_protocol_options_set_min_tls_protocol_version(sec, .TLSv12)
        sec_protocol_options_set_max_tls_protocol_version(sec, .TLSv13)
        // PSK-only TLS exchanges no certificate; the transcript MAC binds
        // both sides to the shared key, which is the authentication. Reading
        // back the negotiated PSK identity (to cross-check the app-layer
        // pairing id) is not possible: Security exposes
        // sec_protocol_metadata_access_pre_shared_keys with a C-only
        // dispatch_data_t that Swift cannot introspect.
        sec_protocol_options_set_verify_block(sec, { _, _, complete in complete(true) }, DispatchQueue.global(qos: .userInitiated))
        return NWParameters(tls: options)
    }

    private static func dispatchData(_ data: Data) -> DispatchData {
        // DispatchData(bytes:) copies the buffer (default destructor), so the
        // result outlives the Data storage.
        data.withUnsafeBytes { DispatchData(bytes: $0) }
    }
}

public class TCPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.tcp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var receiveBuffer = Data()
    private var timeoutWorkItem: DispatchWorkItem?
    private var didNotifyDisconnect = false
    public var security: ChannelSecurity
    private var listenPort: UInt16?

    public var onConnect: (@Sendable () -> Void)?
    public var onDisconnect: (@Sendable () -> Void)?
    public var onReceive: (@Sendable (Data) -> Void)?
    public var onConnectionFailed: (@Sendable () -> Void)?
    public private(set) var lastFailureDescription: String?
    public private(set) var connectionStateDescription: String?

    public var remoteHostIP: String? {
        guard let endpoint = connection?.currentPath?.remoteEndpoint else { return nil }
        if case .hostPort(let host, _) = endpoint { return "\(host)" }
        return nil
    }

    public init(security: ChannelSecurity = .none) {
        self.security = security
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    private var connectionParameters: NWParameters {
        let params = security.tlsParameters ?? NWParameters.tcp
        // Pairing swaps PSKs by restarting the listener; without endpoint
        // reuse the immediate rebind loses the race with the old socket.
        params.allowLocalEndpointReuse = true
        return params
    }

