+    };
+
+    use super::*;
+
+    #[test]
+    fn bootstrap_key_is_deterministic_per_pin() {
+        assert_eq!(bootstrap_psk("12345678").unwrap(), bootstrap_psk("12345678").unwrap());
+        assert_ne!(bootstrap_psk("12345678").unwrap(), bootstrap_psk("87654321").unwrap());
+    }
